type Action = { type: 'LOGIN' } | { type: 'LOGOUT' };
function reducer(action: Action) {
  switch (action.type) {
    case 'LOGIN': return 'In';
    case 'LOGOUT': return 'Out';
    default: {
      const _check: never = action;
      throw new Error(`Unhandled action: ${_check}`);
    }
  }
}

